pub const bun = @import("bun");
pub const install = @import("../install.zig");
pub const Lockfile = @import("../lockfile.zig");
pub const Dependency = @import("../dependency.zig");
pub const Fs = @import("../../resolver/fs.zig");
pub const Path = @import("../../paths/resolve_path.zig");
pub const RootSelection = enum {
    implicit,
    explicit_only,
    pub fn get(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn has(__cp_s: []const u8) bool { return std.meta.stringToEnum(@This(), __cp_s) != null; }
    pub fn fromName(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn name(__cp_self: @This()) []const u8 { return @tagName(__cp_self); }
};

const Allocator = std.mem.Allocator;
const DynamicBitSet = bun.bit_set.DynamicBitSet;
const Global = bun.Global;
const Output = bun.Output;
const glob = bun.glob;
const strings = bun.strings;
const PackageID = install.PackageID;
const PackageNameHash = install.PackageNameHash;
const Behavior = Dependency.Behavior;
pub const Candidate = struct {
    name: []const u8,
    abs_posix_dir: []const u8,
    is_root: bool,
};
pub const LinkTargets = struct {
    importers: []const ?PackageNameHash,

pub fn fromImporters(allocator: Allocator, hashes: []const ?PackageNameHash) LinkTargets!void {
            const duped = try allocator.dupe(?PackageNameHash, hashes);
            return LinkTargets{ .importers = duped };
    }

pub fn deinit(self: *@This(), allocator: Allocator) void {
            _ = allocator.free(self.importers);
    }
};
pub const Selection = struct {
    selected: DynamicBitSet,
    unmatched_patterns: std.array_list.Managed(usize),

pub fn deinit(self: *@This()) void {
            _ = self.selected.deinit();
            _ = self.unmatched_patterns.deinit();
    }
};
pub const LockfileSelection = struct {
    ids: std.array_list.Managed(PackageID),
    unmatched_patterns: std.array_list.Managed(usize),

pub fn deinit(self: *@This()) void {
            _ = self.ids.deinit();
            _ = self.unmatched_patterns.deinit();
    }
};
pub const WorkspaceGraph = struct {
    allocator: Allocator,
    dependencies: []std.array_list.Managed(u32),
    dependents: []std.array_list.Managed(u32),

pub fn deinit(self: *@This()) void {
            for (cp_mut_slice(&self.dependencies)) |*list| {
                _ = &list;
                _ = (list.*).deinit();
            }
            for (cp_mut_slice(&self.dependents)) |*list| {
                _ = &list;
                _ = (list.*).deinit();
            }
            _ = self.allocator.free(self.dependencies);
            _ = self.allocator.free(self.dependents);
    }

pub fn fromLockfile(allocator: Allocator, lockfile: *const Lockfile, candidate_name_hashes: []const ?PackageNameHash) !WorkspaceGraph {
            const n = candidate_name_hashes.len;
            var root_candidate: ?u32 = null;
            _ = &root_candidate;
            var by_hash = std.AutoHashMap(PackageNameHash, u32).init(allocator);
            _ = &by_hash;
            defer {
            _ = by_hash.deinit();
            }
            _ = try by_hash.ensureTotalCapacity(@intCast(n));
            var idx: usize = 0;
            _ = &idx;
            while ((idx < n)) : (idx = (idx + 1)) {
                if (candidate_name_hashes[@as(usize, @intCast(idx))]) |hash| {
                    _ = &hash;
                    _ = by_hash.putAssumeCapacity(hash, @intCast(idx));
                } else {
                    if ((root_candidate == null)) {
                        root_candidate = @intCast(idx);
                    }
                }
            }
            const pkg_resolutions = lockfile.packages.items(.resolution);
            const name_hashes = lockfile.packages.items(.name_hash);
            const res_lists = lockfile.packages.items(.resolutions);
            const dep_lists = lockfile.packages.items(.dependencies);
            const resolutions = lockfile.buffers.resolutions.items;
            const dependencies = lockfile.buffers.dependencies.items;
            var candidate_of = try allocator.alloc(u32, pkg_resolutions.len);
            _ = &candidate_of;
            defer {
            _ = allocator.free(candidate_of);
            }
            var p_i: usize = 0;
            _ = &p_i;
            while ((p_i < pkg_resolutions.len)) : (p_i = (p_i + 1)) {
                const res = pkg_resolutions[@as(usize, @intCast(p_i))];
                candidate_of[cp_cast_int(usize, p_i)] = (switch (res.tag) {
.root => ((root_candidate) orelse (std.math.maxInt(u32))),
.workspace => ((by_hash.get(name_hashes[@as(usize, @intCast(p_i))])) orelse (std.math.maxInt(u32))),
else => std.math.maxInt(u32),
});
            }
            var deps_adj = try allocator.alloc(std.array_list.Managed(u32), n);
            _ = &deps_adj;
            errdefer {
            _ = allocator.free(deps_adj);
            }
            var dependents_adj = try allocator.alloc(std.array_list.Managed(u32), n);
            _ = &dependents_adj;
            errdefer {
            _ = allocator.free(dependents_adj);
            }
            var j: usize = 0;
            _ = &j;
            while ((j < n)) : (j = (j + 1)) {
                deps_adj[cp_cast_int(usize, j)] = std.array_list.Managed(u32).init(allocator);
                dependents_adj[cp_cast_int(usize, j)] = std.array_list.Managed(u32).init(allocator);
            }
            var graph = WorkspaceGraph{ .allocator = allocator, .dependencies = deps_adj, .dependents = dependents_adj };
            _ = &graph;
            errdefer {
            _ = graph.deinit();
            }
            p_i = 0;
            while ((p_i < pkg_resolutions.len)) : (p_i = (p_i + 1)) {
                const from_idx = candidate_of[@as(usize, @intCast(p_i))];
                if ((from_idx == std.math.maxInt(u32))) {
                    continue;
                }
                const dep_slice = dep_lists[@as(usize, @intCast(p_i))];
                const res_slice = res_lists[@as(usize, @intCast(p_i))];
                const dep_items = dep_slice.get(dependencies);
                const res_items = res_slice.get(resolutions);
                var k: usize = 0;
                _ = &k;
                while ((k < dep_items.len)) : (k = (k + 1)) {
                    if (dep_items[@as(usize, @intCast(k))].behavior.workspace) {
                        continue;
                    }
                    const dep_pkg = res_items[@as(usize, @intCast(k))];
                    if ((dep_pkg >= candidate_of.len)) {
                        continue;
                    }
                    const to_idx = candidate_of[@as(usize, @intCast(dep_pkg))];
                    if (((to_idx == std.math.maxInt(u32)) or (to_idx == from_idx))) {
                        continue;
                    }
                    _ = try graph.dependencies[@as(usize, @intCast(from_idx))].append(to_idx);
                    _ = try graph.dependents[@as(usize, @intCast(to_idx))].append(from_idx);
                }
            }
            return graph;
    }
};
const BaseKind = enum {
    all,
    name,
    path,
    subtree,
};
const Base = union(BaseKind) {
    all: void,
    name: []const u8,
    path: []const u8,
    subtree: []const u8,
};
const Selector = struct {
    negated: bool,
    dependencies: bool,
    dependents: bool,
    exclude_self: bool,
    base: Base,
    owned_buf: ?[]u8,
};

pub fn stripNegations(raw: []const u8) struct { remain: []const u8, negated: bool } {
        var remain = raw;
        _ = &remain;
        var negated = false;
        _ = &negated;
        while (strings.hasPrefixComptime(remain, "!")) {
            negated = (!negated);
            remain = remain[1..];
        }
        return .{ .remain = remain, .negated = negated };
}

pub fn parseSelector(allocator: Allocator, raw: []const u8, original_cwd: []const u8, path_buf: *bun.PathBuffer) !Selector {
        const stripped = stripNegations(raw);
        var remain = stripped.remain;
        _ = &remain;
        const negated = stripped.negated;
        var dependencies = false;
        _ = &dependencies;
        var dependents = false;
        _ = &dependents;
        var exclude_self = false;
        _ = &exclude_self;
        if (strings.hasPrefixComptime(remain, "...")) {
            dependents = true;
            remain = remain[3..];
            if (strings.hasPrefixComptime(remain, "^")) {
                exclude_self = true;
                remain = remain[1..];
            }
        }
        if (strings.endsWithComptime(remain, "...")) {
            dependencies = true;
            remain = remain[0..(remain.len - 3)];
            if (strings.endsWithComptime(remain, "^")) {
                exclude_self = true;
                remain = remain[0..(remain.len - 1)];
            }
        }
        if (((dependencies or dependents) and (remain.len == 0))) {
            _ = Output.errGeneric("--filter \"{s}\" is missing a workspace name or path", .{ raw });
            _ = Global.crash();
        }
        var owned_buf: ?[]u8 = null;
        _ = &owned_buf;
        var base: Base = Base{ .name = remain };
        _ = &base;
        if ((strings.eqlComptime(remain, "*") or strings.eqlComptime(remain, "**"))) {
            base = Base.all;
        } else {
            if ((((remain.len >= 2) and (remain[0] == 123)) and (remain[@as(usize, @intCast((remain.len - 1)))] == 125))) {
                const parts: [1][]const u8 = .{ remain[1..(remain.len - 1)] };
                const joined = strings.withoutTrailingSlash(Path.joinAbsStringBuf(original_cwd, path_buf, (&parts), .posix));
                const dup = try allocator.dupe(u8, joined);
                owned_buf = dup;
                base = Base{ .subtree = dup };
            } else {
                if (((remain.len > 0) and (remain[0] == 46))) {
                    const parts: [1][]const u8 = .{ remain };
                    const joined = strings.withoutTrailingSlash(Path.joinAbsStringBuf(original_cwd, path_buf, (&parts), .posix));
                    const dup = try allocator.dupe(u8, joined);
                    owned_buf = dup;
                    base = Base{ .path = dup };
                }
            }
        }
        return Selector{ .negated = negated, .dependencies = dependencies, .dependents = dependents, .exclude_self = exclude_self, .base = base, .owned_buf = owned_buf };
}

pub fn baseMatches(base: Base, c: Candidate, explicit_root_only: bool) bool {
        return (switch (base) {
.all => (if (c.is_root) (!explicit_root_only) else ((if (@typeInfo(@TypeOf(c)) == .@"enum" or @typeInfo(@TypeOf(c)) == .@"union") @tagName(c) else c.name).len > 0)),
.name => |pat| glob.match(pat, (if (@typeInfo(@TypeOf(c)) == .@"enum" or @typeInfo(@TypeOf(c)) == .@"union") @tagName(c) else c.name)).matches(),
.path => |pat| glob.match(pat, c.abs_posix_dir).matches(),
.subtree => |pat| {
{
            var dir = c.abs_posix_dir;
            _ = &dir;
            while (true) {
                if (glob.match(pat, dir).matches()) {
                    return true;
                }
                if (strings.lastIndexOfChar(dir, 47)) |i| {
                    _ = &i;
                    if ((i > 0)) {
                        dir = dir[0..i];
                        continue;
                    }
                }
                return false;
            }
        }
},
});
}

pub fn walkGraph(allocator: Allocator, graph: *const WorkspaceGraph, sel: Selector, base: *const DynamicBitSet, unreachable_idx: ?usize) !DynamicBitSet {
        const n = base.capacity();
        var reached = try DynamicBitSet.initEmpty(allocator, n);
        _ = &reached;
        errdefer {
        _ = reached.deinit();
        }
        var visited = try DynamicBitSet.initEmpty(allocator, n);
        _ = &visited;
        defer {
        _ = visited.deinit();
        }
        var queue = std.array_list.Managed(u32).init(allocator);
        _ = &queue;
        defer {
        _ = queue.deinit();
        }
        const dirs: [2]bool = .{ sel.dependencies, sel.dependents };
        var pass: usize = 0;
        _ = &pass;
        while ((pass < 2)) : (pass = (pass + 1)) {
            if ((!dirs[@as(usize, @intCast(pass))])) {
                continue;
            }
            const adjacency = (if ((pass == 0)) graph.dependencies else graph.dependents);
            var base_unmanaged = (blk: {
            break :blk @constCast((&base.unmanaged));

});
            _ = &base_unmanaged;
            _ = base_unmanaged.copyInto(visited.unmanaged);
            if (unreachable_idx) |ui| {
                _ = &ui;
                _ = visited.set(ui);
            }
            var it = base.iterator(.{});
            _ = &it;
            while (it.next()) |i| {
                _ = try queue.append(@intCast(i));
            }
            var head: usize = 0;
            _ = &head;
            while ((head < queue.items.len)) : (head = (head + 1)) {
                const u = queue.items[@as(usize, @intCast(head))];
                for (adjacency[@as(usize, @intCast(u))].items) |v| {
                    _ = &v;
                    if ((!visited.isSet(v))) {
                        _ = visited.set(v);
                        _ = try queue.append(v);
                    }
                }
            }
            _ = queue.clearRetainingCapacity();
            _ = reached.unmanaged.setUnion(visited.unmanaged);
        }
        if (sel.exclude_self) {
            _ = reached.unmanaged.setExclude(base.unmanaged);
        } else {
            _ = reached.unmanaged.setUnion(base.unmanaged);
        }
        if (unreachable_idx) |ui| {
            _ = &ui;
            if ((!base.isSet(ui))) {
                _ = reached.unset(ui);
            }
        }
        return reached;
}

pub fn firstRelational(patterns: []const []const u8) ?[]const u8 {
        for (cp_iter_slice(patterns)) |raw| {
            _ = &raw;
            const stripped = stripNegations(raw);
            const trimmed = stripped.remain;
            if ((strings.hasPrefixComptime(trimmed, "...") or strings.endsWithComptime(trimmed, "..."))) {
                return raw;
            }
        }
        return null;
}

pub fn select(allocator: Allocator, patterns: []const []const u8, original_cwd: []const u8, candidates: []const Candidate, graph: ?*const WorkspaceGraph, root: RootSelection) !Selection {
        const n = candidates.len;
        const explicit_root_only = ((root == .explicit_only) and (n > 1));
        var root_index: ?usize = null;
        _ = &root_index;
        if (explicit_root_only) {
            var i: usize = 0;
            _ = &i;
            while ((i < n)) : (i = (i + 1)) {
                if (candidates[@as(usize, @intCast(i))].is_root) {
                    root_index = i;
                    break;
                }
            }
        }
        var include = try DynamicBitSet.initEmpty(allocator, n);
        _ = &include;
        errdefer {
        _ = include.deinit();
        }
        var exclude = try DynamicBitSet.initEmpty(allocator, n);
        _ = &exclude;
        defer {
        _ = exclude.deinit();
        }
        var any_positive = false;
        _ = &any_positive;
        var unmatched_patterns = std.array_list.Managed(usize).init(allocator);
        _ = &unmatched_patterns;
        errdefer {
        _ = unmatched_patterns.deinit();
        }
        var path_buf: bun.PathBuffer = undefined;
        _ = &path_buf;
        var pat_i: usize = 0;
        _ = &pat_i;
        while ((pat_i < patterns.len)) : (pat_i = (pat_i + 1)) {
            const raw = patterns[@as(usize, @intCast(pat_i))];
            const sel = try parseSelector(allocator, raw, original_cwd, (&path_buf));
            defer {
            if (sel.owned_buf) |ob| {
                _ = &ob;
                _ = allocator.free(ob);
            }
            }
            var set = try DynamicBitSet.initEmpty(allocator, n);
            _ = &set;
            defer {
            _ = set.deinit();
            }
            var i: usize = 0;
            _ = &i;
            while ((i < n)) : (i = (i + 1)) {
                if (baseMatches(sel.base, candidates[@as(usize, @intCast(i))], explicit_root_only)) {
                    _ = set.set(i);
                }
            }
            if ((sel.dependencies or sel.dependents)) {
                if (graph) |g| {
                    _ = &g;
                    var walked = try walkGraph(allocator, g, sel, (&set), root_index);
                    _ = &walked;
                    defer {
                    _ = walked.deinit();
                    }
                    _ = walked.unmanaged.copyInto(set.unmanaged);
                }
            }
            if (sel.negated) {
                _ = exclude.unmanaged.setUnion(set.unmanaged);
            } else {
                any_positive = true;
                if ((set.count() == 0)) {
                    _ = try unmatched_patterns.append(pat_i);
                }
                _ = include.unmanaged.setUnion(set.unmanaged);
            }
        }
        if ((!any_positive)) {
            var i: usize = 0;
            _ = &i;
            while ((i < n)) : (i = (i + 1)) {
                if (baseMatches(Base.all, candidates[@as(usize, @intCast(i))], explicit_root_only)) {
                    _ = include.set(i);
                }
            }
        }
        _ = include.unmanaged.setExclude(exclude.unmanaged);
        return Selection{ .selected = include, .unmatched_patterns = unmatched_patterns };
}

pub fn selectLockfileWorkspaces(allocator: Allocator, lockfile: *const Lockfile, patterns: []const []const u8, original_cwd: []const u8, root: RootSelection) !LockfileSelection {
        const pkg_resolutions = lockfile.packages.items(.resolution);
        var ids = std.array_list.Managed(PackageID).init(allocator);
        _ = &ids;
        errdefer {
        _ = ids.deinit();
        }
        var p_i: usize = 0;
        _ = &p_i;
        while ((p_i < pkg_resolutions.len)) : (p_i = (p_i + 1)) {
            const tag = pkg_resolutions[@as(usize, @intCast(p_i))].tag;
            if (((tag == .root) or (tag == .workspace))) {
                _ = try ids.append(@intCast(p_i));
            }
        }
        var unmatched_empty = std.array_list.Managed(usize).init(allocator);
        _ = &unmatched_empty;
        errdefer {
        _ = unmatched_empty.deinit();
        }
        if ((patterns.len == 0)) {
            return LockfileSelection{ .ids = ids, .unmatched_patterns = unmatched_empty };
        }
        const pkg_names = lockfile.packages.items(.name);
        const name_hashes = lockfile.packages.items(.name_hash);
        const string_buf = lockfile.buffers.string_bytes.items;
        const top_level_dir = Fs.FileSystem.instance.top_level_dir;
        var dirs = try allocator.alloc([]u8, ids.items.len);
        _ = &dirs;
        var dirs_init: usize = 0;
        _ = &dirs_init;
        defer {
        {
            var d_i: usize = 0;
            _ = &d_i;
            while ((d_i < dirs_init)) : (d_i = (d_i + 1)) {
                _ = allocator.free(dirs[@as(usize, @intCast(d_i))]);
            }
            _ = allocator.free(dirs);
        }
        }
        var candidates = try allocator.alloc(Candidate, ids.items.len);
        _ = &candidates;
        defer {
        _ = allocator.free(candidates);
        }
        var path_buf: bun.PathBuffer = undefined;
        _ = &path_buf;
        var idx: usize = 0;
        _ = &idx;
        while ((idx < ids.items.len)) : (idx = (idx + 1)) {
            const pkg_id = ids.items[@as(usize, @intCast(idx))];
            const res = pkg_resolutions[@as(usize, @intCast(pkg_id))];
            const rel: []const u8 = (if ((res.tag == .workspace)) (if (@typeInfo(@TypeOf(res)) == .@"enum") @intFromEnum(res) else res.value).workspace.slice(string_buf) else ".");
            const parts: [1][]const u8 = .{ rel };
            const joined = strings.withoutTrailingSlash(Path.joinAbsStringBuf(top_level_dir, (&path_buf), (&parts), .posix));
            dirs[cp_cast_int(usize, idx)] = try allocator.dupe(u8, joined);
            dirs_init = (dirs_init + 1);
            candidates[cp_cast_int(usize, idx)] = Candidate{ .name = pkg_names[@as(usize, @intCast(pkg_id))].slice(string_buf), .abs_posix_dir = dirs[@as(usize, @intCast(idx))], .is_root = (res.tag == .root) };
        }
        var graph: ?WorkspaceGraph = null;
        _ = &graph;
        defer {
        if (graph) |*g| {
            _ = &g;
            _ = (g.*).deinit();
        }
        }
        if ((firstRelational(patterns) != null)) {
            var hashes = try allocator.alloc(?PackageNameHash, ids.items.len);
            _ = &hashes;
            defer {
            _ = allocator.free(hashes);
            }
            idx = 0;
            while ((idx < ids.items.len)) : (idx = (idx + 1)) {
                const pkg_id = ids.items[@as(usize, @intCast(idx))];
                hashes[cp_cast_int(usize, idx)] = (if (candidates[@as(usize, @intCast(idx))].is_root) null else name_hashes[@as(usize, @intCast(pkg_id))]);
            }
            graph = try WorkspaceGraph.fromLockfile(allocator, lockfile, hashes);
        }
        const graph_ptr: ?*const WorkspaceGraph = (if ((graph != null)) (&graph.?) else null);
        var sel = try select(allocator, patterns, original_cwd, candidates, graph_ptr, root);
        _ = &sel;
        defer {
        _ = sel.selected.deinit();
        }
        var write_idx: usize = 0;
        _ = &write_idx;
        idx = 0;
        while ((idx < ids.items.len)) : (idx = (idx + 1)) {
            if (sel.selected.isSet(idx)) {
                ids.items[cp_cast_int(usize, write_idx)] = ids.items[@as(usize, @intCast(idx))];
                write_idx = (write_idx + 1);
            }
        }
        ids.items.len = write_idx;
        _ = unmatched_empty.deinit();
        return LockfileSelection{ .ids = ids, .unmatched_patterns = sel.unmatched_patterns };
}

pub fn unmatchedMessage(allocator: Allocator, patterns: []const []const u8) ![]u8 {
        var out = std.array_list.Managed(u8).init(allocator);
        _ = &out;
        errdefer {
        _ = out.deinit();
        }
        if ((patterns.len == 1)) {
            _ = try out.appendSlice("No workspace packages matched the filter ");
        } else {
            _ = try out.appendSlice("No workspace packages matched the filters ");
        }
        var i: usize = 0;
        _ = &i;
        while ((i < patterns.len)) : (i = (i + 1)) {
            if ((i > 0)) {
                _ = try out.appendSlice(", ");
            }
            _ = try out.append(34);
            _ = try out.appendSlice(patterns[@as(usize, @intCast(i))]);
            _ = try out.append(34);
        }
        return out.toOwnedSlice();
}

pub fn warnUnmatched(allocator: Allocator, patterns: []const []const u8, unmatched_patterns: []const usize) void {
        if ((unmatched_patterns.len == 0)) {
            return;
        }
        var unmatched = (blk_catch_0: { break :blk_catch_0 ((allocator.alloc([]const u8, unmatched_patterns.len)) catch |__ce_0| { _ = &__ce_0; return; }); });
        _ = &unmatched;
        defer {
        _ = allocator.free(unmatched);
        }
        var i: usize = 0;
        _ = &i;
        while ((i < unmatched_patterns.len)) : (i = (i + 1)) {
            unmatched[cp_cast_int(usize, i)] = patterns[@as(usize, @intCast(unmatched_patterns[@as(usize, @intCast(i))]))];
        }
        const msg = (blk_catch_1: { break :blk_catch_1 ((unmatchedMessage(allocator, unmatched)) catch |__ce_1| { _ = &__ce_1; return; }); });
        defer {
        _ = allocator.free(msg);
        }
        _ = Output.warn("{s}", .{ msg });
}
